def f(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    other=[x for x in cnt if x!=bg]
    # find rows/cols fully one "other" color vs mixed
    rows_full={i if g[i] and all(x==g[i][0] for x in g[i]) else None for i in range(h)}
    full_rows=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg]
    full_cols=[j for j in range(w) if len({g[i][j] for i in range(h)})==1 and g[0][j]!=bg]
    mark=set()
    for i in full_rows:
        for j in range(w):
            if g[i][j]==bg: mark.add((i,j))
    for j in full_cols:
        for i in range(h):
            if g[i][j]==bg: mark.add((i,j))
    return [[1 if (i,j) in mark else g[i][j] for j in range(w)] for i in range(h)]
